    int node = 0;
    for (int b = 30; b >= 0; b--) {
        int bit = (x >> b) & 1;
        if (child[node][bit] == -1) {
            child[node][bit] = (int)child.size();
            child.push_back({-1, -1});
        }
        node = child[node][bit];
    }
}

