int queryMaxXor(int x) {
    int node = 0;
    int res = 0;
    for (int b = 30; b >= 0; b--) {
        int bit = (x >> b) & 1;
        int want = bit ^ 1;          // 相反的位
        // 优先走相反位，使当前位异或结果为 1
        if (child[node][want] != -1) {
            res |= 1 << b;
            node = child[node][want];
        } else {
            node = child[node][bit];
        }
    }
    return res;
}

